{
  "name": "@wafonro2/opencode-resurrect",
  "version": "0.1.1",
  "description": "OpenCode plugin that saves and restores the latest session per project",
  "type": "module",
  "main": "index.js",
  "exports": {
    ".": "./index.js"
  },
  "files": [
    "index.js",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "session",
    "restore"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/wafonro2/opencode-resurrect.git"
  },
  "homepage": "https://github.com/wafonro2/opencode-resurrect#readme",
  "bugs": {
    "url": "https://github.com/wafonro2/opencode-resurrect/issues"
  },
  "license": "MIT",
  "publishConfig": {
    "access": "public"
  }
}

import { writeFile, readFile, readdir, stat } from "node:fs/promises"
import { join } from "node:path"

const FILE_PREFIX = ".opencode-session"
const LEGACY_FILE_PREFIX = "opencode-session"
const FILE_EXTENSION = ".txt"
const cache = new Map()
const sessionFileBySessionKey = new Map()
const restoredDirectories = new Set()
const RESTORE_DELAY_MS = 750

const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms))

const formatCreationDateForFileName = (date = new Date()) => {
  const year = date.getFullYear()
  const month = String(date.getMonth() + 1).padStart(2, "0")
  const day = String(date.getDate()).padStart(2, "0")
  const hours = String(date.getHours()).padStart(2, "0")
  const minutes = String(date.getMinutes()).padStart(2, "0")
  const seconds = String(date.getSeconds()).padStart(2, "0")
  const milliseconds = String(date.getMilliseconds()).padStart(3, "0")
  return `${year}${month}${day}-${hours}${minutes}${seconds}${milliseconds}`
}

const getSessionFilePath = (session) => {
  const sessionKey = `${session.directory}::${session.id}`
  const cachedFilePath = sessionFileBySessionKey.get(sessionKey)
  if (cachedFilePath) return cachedFilePath

  const createdAt = formatCreationDateForFileName()
  const filePath = join(session.directory, `${FILE_PREFIX}-${createdAt}${FILE_EXTENSION}`)
  sessionFileBySessionKey.set(sessionKey, filePath)
  return filePath
}

const writeSessionId = async (session, logger) => {
  if (!session?.directory || !session?.id) return

  const filePath = getSessionFilePath(session)
  const serialized = `${session.id}\n`

  if (cache.get(filePath) === serialized) return

  try {
    await writeFile(filePath, serialized, "utf8")
    cache.set(filePath, serialized)
  } catch (error) {
    await logger(
      "error",
      "opencode-resurrect: failed to write session id",
      { sessionID: session.id, filePath, error: error?.message }
    )
  }
}

const findLatestSessionFile = async (directory, logger) => {
  let entries
  try {
    entries = await readdir(directory)
  } catch (error) {
    await logger("error", "opencode-resurrect: failed to read directory", {
      directory,
      error: error?.message,
    })
    return null
  }

  const candidates = await Promise.all(
    entries.map(async (name) => {
      if (!name.endsWith(FILE_EXTENSION)) return null
      const isCurrentFormat = name.startsWith(`${FILE_PREFIX}-`)
      const isLegacyFormat = name.startsWith(`${LEGACY_FILE_PREFIX}-`)
      if (!isCurrentFormat && !isLegacyFormat) return null
      const filePath = join(directory, name)
      try {
        const info = await stat(filePath)
        return { filePath, mtime: info.mtimeMs }
      } catch (error) {
        await logger("error", "opencode-resurrect: failed to stat session file", {
          filePath,
          error: error?.message,
        })
        return null
      }
    }),
  )

  const filtered = candidates.filter(Boolean)
  if (!filtered.length) return null

  filtered.sort((a, b) => b.mtime - a.mtime)
  return filtered[0].filePath
}

const readSessionIdFromFile = async (filePath, logger) => {
  try {
    const contents = await readFile(filePath, "utf8")
    const sessionID = contents.split(/\r?\n/)[0]?.trim()
    if (!sessionID) {
      await logger("error", "opencode-resurrect: session file empty", { filePath })
      return null
    }
    return sessionID
  } catch (error) {
    await logger("error", "opencode-resurrect: failed to read session file", {
      filePath,
      error: error?.message,
    })
    return null
  }
}

const restoreSessionFromDisk = async ({ client, directory, logger }) => {
  if (restoredDirectories.has(directory)) return

  const filePath = await findLatestSessionFile(directory, logger)
  if (!filePath) return

  const sessionID = await readSessionIdFromFile(filePath, logger)
  if (!sessionID) return

  await logger("info", "opencode-resurrect: attempting session restore", {
    sessionID,
    filePath,
  })

  try {
    const result = await client.session.get({
      path: { id: sessionID },
      query: { directory },
    })

    if (!result?.data?.id) {
      await logger("error", "opencode-resurrect: session not found", {
        sessionID,
        directory,
      })
      return
    }
  } catch (error) {
    await logger("error", "opencode-resurrect: failed to verify session", {
      sessionID,
      directory,
      error: error?.message,
    })
    return
  }

  try {
    await client.tui.publish({
      body: {
        type: "tui.session.select",
        properties: { sessionID },
      },
      query: { directory },
    })
    restoredDirectories.add(directory)
    await logger("info", "opencode-resurrect: restored session", {
      sessionID,
      filePath,
    })
  } catch (error) {
    await logger("error", "opencode-resurrect: failed to publish session restore event", {
      sessionID,
      error: error?.message,
    })
  }
}

export const OpencodeResurrectPlugin = async ({ client, directory }) => {
  const logger = async (level, message, extra) => {
    try {
      await client.app.log({
        body: {
          service: "opencode-resurrect",
          level,
          message,
          extra,
        },
      })
    } catch {
      // Swallow logging failures to avoid infinite loops
    }
  }

  const scheduleRestore = () => {
    if (!directory) return
    wait(RESTORE_DELAY_MS)
      .then(() => restoreSessionFromDisk({ client, directory, logger }))
      .catch(async (error) => {
        await logger("error", "opencode-resurrect: restore scheduling failed", {
          directory,
          error: error?.message,
        })
      })
  }

  if (!directory) {
    await logger("warn", "opencode-resurrect: directory not provided, skipping auto-restore")
  } else {
    scheduleRestore()
  }

  return {
    event: async ({ event }) => {
      if (event.type === "server.connected") {
        scheduleRestore()
        return
      }

      if (
        event.type === "session.created" ||
        event.type === "session.updated" ||
        event.type === "session.deleted"
      ) {
        await writeSessionId(event.properties.info, logger)
      }
    },
  }
}

export default OpencodeResurrectPlugin
